// Normalise the logging payload from every call site into one shape.
//
// The field that has to be right is wa_message_id: it is the dedup key that makes
// a retried Meta webhook delivery harmless.

const input = $input.first().json;
const str = (v) => (v === undefined || v === null ? '' : String(v));

const direction = str(input.direction).toLowerCase() === 'out' ? 'out' : 'in';
const actor = str(input.actor) || (direction === 'in' ? 'customer' : 'ai');

// Meta sends seconds since epoch. Outbound sends carry no timestamp of their own,
// so the call site passes the send time instead.
const rawTimestamp = str(input.wa_timestamp);
const timestampSeconds = /^\d+$/.test(rawTimestamp)
  ? Number(rawTimestamp)
  : Math.floor(Date.now() / 1000);

// A send Meta never acknowledged still has to be recorded. Synthesise a key rather
// than writing an empty one: empty keys would all collide with each other and the
// dedup lookup would start discarding real messages.
let waMessageId = str(input.wa_message_id).trim();
if (!waMessageId) {
  waMessageId = `unacked-${direction}-${timestampSeconds}-${Math.random().toString(36).slice(2, 10)}`;
}

const raw = typeof input.raw === 'string' ? input.raw : JSON.stringify(input.raw ?? null);
const MAX_RAW_CHARS = 8000;

return [{
  json: {
    wa_message_id: waMessageId,
    phone: str(input.phone).replace(/[^0-9]/g, ''),
    wa_profile_name: str(input.wa_profile_name),
    direction,
    actor,
    msg_type: str(input.msg_type) || 'text',
    body: str(input.body),
    media_id: str(input.media_id),
    wa_timestamp: new Date(timestampSeconds * 1000).toISOString(),
    logged_at: new Date().toISOString(),
    raw: raw.length > MAX_RAW_CHARS ? `${raw.slice(0, MAX_RAW_CHARS)}...[truncated]` : raw,
  },
}];

// Decide whether this message continues the newest conversation for this phone
// number or starts a new one.
//
// SESSION_IDLE_MINUTES is an operational grouping boundary and nothing else: it
// decides where one transcript ends and the next begins. Nothing outside this node
// reads it, no downstream logic assumes a particular value, and changing it only
// changes how future messages are grouped. Do not build business rules on it.
const SESSION_IDLE_MINUTES = 24 * 60;

const message = $('Normalize Input').first().json;

// Find Open Conversation returns every conversation for this phone number and the
// newest is the only candidate. Picking it here rather than with the node's sort
// option is deliberate: that option is not applied, so a sort plus limit 1 hands
// back the OLDEST row and pins every message to the first conversation ever opened
// for the number.
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && (row.Id ?? row.id) != null);

let newest = null;
for (const row of rows) {
  if (!newest || Number(row.Id ?? row.id) > Number(newest.Id ?? newest.id)) newest = row;
}

let reuse = false;
if (newest) {
  const lastSeen = Date.parse(newest.last_message_at || newest.started_at || '');
  const idleMinutes = Number.isNaN(lastSeen) ? Infinity : (Date.now() - lastSeen) / 60000;
  reuse = idleMinutes < SESSION_IDLE_MINUTES;
}

if (reuse) {
  return [{ json: { ...newest, Id: newest.Id ?? newest.id, needs_new_conversation: false } }];
}

return [{
  json: {
    needs_new_conversation: true,
    phone: message.phone,
    wa_profile_name: message.wa_profile_name,
    started_at: message.wa_timestamp,
  },
}];

// Convergence point for both branches — conversation reused, or just created.
// Everything downstream reaches back to this node, so it must always run and must
// always carry the resolved conversation id.

const message = $('Normalize Input').first().json;
const conversation = $input.first().json || {};
const conversationId = conversation.Id ?? conversation.id ?? null;

if (!conversationId) {
  // Writing the message anyway would produce a row that belongs to no conversation
  // and would never appear in any transcript. Fail loudly instead.
  throw new Error('No conversation id resolved - refusing to write an orphan message row');
}

return [{ json: { ...message, conversation_id: String(conversationId) } }];

// Rebuild the transcript from the message rows.
//
// This is a projection, not an accumulator. It is rewritten in full on every turn,
// so a lost or out-of-order update heals on the next message instead of leaving a
// permanent hole. Never change this to append.

const MAX_LINES = 100;
const ACTOR_LABELS = { customer: 'Client', ai: 'Bot', system: 'System', human_agent: 'Agent' };

const prepared = $('Prepare Message Row').first().json;
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.wa_message_id);

rows.sort((a, b) => {
  const ta = Date.parse(a.wa_timestamp) || 0;
  const tb = Date.parse(b.wa_timestamp) || 0;
  // Meta timestamps are second-granular, so a reply can share a second with the
  // message it answers. Id breaks the tie because rows are inserted in turn order.
  return ta !== tb ? ta - tb : Number(a.Id || 0) - Number(b.Id || 0);
});

const shown = rows.length > MAX_LINES ? rows.slice(-MAX_LINES) : rows;
const header = rows.length > MAX_LINES
  ? `[... ${rows.length - MAX_LINES} earlier messages omitted - full record in the Messages table ...]\n\n`
  : '';

const lines = shown.map((row) => {
  const when = String(row.wa_timestamp || '').replace('T', ' ').slice(0, 16);
  const who = (ACTOR_LABELS[row.actor] || row.actor || 'Unknown').padEnd(6, ' ');
  const body = String(row.body || '').trim();
  const text = body || `<${row.msg_type || 'unknown'}${row.media_id ? ` ${row.media_id}` : ''}>`;
  return `[${when}] ${who}: ${text}`;
});

const newest = rows[rows.length - 1] || {};

return [{
  json: {
    conversation_id: prepared.conversation_id,
    transcript: header + lines.join('\n'),
    message_count: rows.length,
    last_message_at: newest.wa_timestamp || prepared.wa_timestamp,
  },
}];
